import React, { useEffect, useState } from "react";
import {
  Modal,
  Form,
  Input,
  InputNumber,
  Select,
  DatePicker,
  TimePicker,
  Row,
  Col,
  Divider,
  Alert,
} from "antd";
import baseAPI from "../api/baseAPI";

const { Option } = Select;
export default function BookingRoomModal({ open, room, onClose, onFinish }) {
  const [form] = Form.useForm();
  const [dateTime, setDateTime] = useState({
    date: null,
    start_time: null,
    end_time: null,
  });

  const [bookingError, setBookingError] = useState(null);
  // const [bookingSuccess, setBookingSuccess] = useState();

  const onSubmit = async (data) => {
    try {
      const res = await baseAPI.post(`/meetingrooms/booking`, data);

      if (res.status === 201) {
        setBookingError("");
        form.resetFields();

        onFinish(true);

        // Modal.success({
        //   title: `จองห้อง ${data.title} สำเร็จ`,
        //   content: "เจ้าหน้าที่จะโทรไปยืนยันวันจองในเวลาทำการ",
        // });
      } else if (res.status === 200) {
        console.log(res.data);
        setBookingError("ขออภัยวันและเวลาดังกล่าวถูกจองแล้ว");
        // console.log(res.data);
        // setData(res.data);
      }
    } catch (err) {
      console.error("Booking Error:", err);
      Modal.error({
        title: "เกิดข้อผิดพลาด",
        content: "ไม่สามารถทำรายการจองได้ กรุณาลองใหม่อีกครั้ง",
      });
    }
  };
  const handleSubmit = (values) => {
    const submit = {
      ...room,
      room_id: room.id,
      ...values,
      date: dateTime.date,
      start_time: dateTime.start_time + ":00",
      end_time: dateTime.end_time + ":00",
    };

    onSubmit(submit);
  };

  useEffect(() => {
    console.log("Date", dateTime);
  }, [dateTime]);

  const handleFinishFailed = (error) => {
    console.log("Error", error);
  };

  const onChangeDate = (_, dateString) => {
    setDateTime({
      ...dateTime,
      date: dateString,
    });
  };

  const onChangeStartTime = (_, dateString) => {
    setDateTime({
      ...dateTime,
      start_time: dateString,
    });
  };

  const onChangeEndTime = (_, dateString) => {
    setDateTime({
      ...dateTime,
      end_time: dateString,
    });
  };

  const handleCancel = () => {
    // setIsModalOpen(false);
    form.resetFields();
    onClose(false);
  };

  return (
    <div>
      <Modal
        title={`ติดต่อจอง ${room?.title}`}
        open={open}
        onOk={form.submit}
        onCancel={handleCancel}
        cancelText="ยกเลิก"
        okText="ส่งข้อมูล"
        destroyOnClose
      >
        <Divider />
        <Form
          layout="vertical"
          form={form}
          onFinish={handleSubmit}
          onFinishFailed={handleFinishFailed}
        >
          <Row gutter={16}>
            {/* <Col xs={24} sm={6}>
              <Form.Item
                name="salutation"
                label="Salutation"
                rules={[{ required: true }]}
              >
                <Select>
                  <Option value="Mr">Mr</Option>
                  <Option value="Mrs">Mrs</Option>
                  <Option value="Ms">Ms</Option>
                  <Option value="Dr">Dr</Option>
                </Select>
              </Form.Item>
            </Col> */}
            <Col xs={24} sm={24}>
              <Form.Item
                name="booked_by"
                label="ชื่อผู้จอง หรือชื่อหน่วยงาน"
                rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
              >
                <Input />
              </Form.Item>
            </Col>
          </Row>

          <Form.Item
            name="phone"
            label="เบอร์โทรศัพท์"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input />
          </Form.Item>

          <Form.Item
            name="email"
            label="Email"
            // rules={[{ required: true, type: "email" }]}
          >
            <Input />
          </Form.Item>

          <Form.Item
            name="number_attendees"
            label="จำนวนผู้เข้าร่วม"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <InputNumber style={{ width: "100%" }} />
          </Form.Item>
          {/* <Form.Item
            name="location"
            label="Choose a location"
            rules={[{ required: true }]}
          >
            <Select>
              <Option value="Thailand">Thailand</Option>
              <Option value="Bangkok">Bangkok</Option>
              <Option value="Mercury Tower, Thailand">
                Mercury Tower, Thailand
              </Option>
            </Select>
          </Form.Item> */}

          <Row gutter={16}>
            <Col xs={24} sm={8}>
              <Form.Item
                name="date"
                label="จองวันที่"
                rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
              >
                <DatePicker
                  style={{ width: "100%" }}
                  format="YYYY-MM-DD"
                  onChange={onChangeDate}
                />
              </Form.Item>
            </Col>
            <Col xs={24} sm={8}>
              <Form.Item
                name="start_time"
                label="จากเวลา"
                rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
              >
                <TimePicker
                  style={{ width: "100%" }}
                  format="HH:mm"
                  onChange={onChangeStartTime}
                />
              </Form.Item>
            </Col>
            <Col xs={24} sm={8}>
              <Form.Item
                name="end_time"
                label="ถึงเวลา"
                rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
              >
                <TimePicker
                  style={{ width: "100%" }}
                  format="HH:mm"
                  onChange={onChangeEndTime}
                />
              </Form.Item>
            </Col>
          </Row>

          {bookingError && (
            <Alert
              message={bookingError}
              type="error"
              showIcon
              style={{ marginBottom: 16 }}
            />
          )}

          <Form.Item name="purpose" label="ความคิดเห็นเพิ่มเติม">
            <Input.TextArea rows={3} />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
}
