const { Text } = Typography;

export default function BookingPage() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedRoom, setSelectedRoom] = useState(null);
  const [rooms, setRooms] = useState([]);

  useEffect(() => {
    fetchMeetingRoomList();
  }, []);

  const fetchMeetingRoomList = async () => {
    const result = await baseAPI.get(`/meetingrooms`);
    // console.log("DATA", result.data);
    setRooms(result.data);
  };

  const handleFinishBook = (data) => {
    console.log(data);
    // bookingRoom(data);
    // setIsModalOpen(false);
  };

  const showModal = (room) => {
    setSelectedRoom(room);
    setIsModalOpen(true);
  };

  return (
    <div className="booking-container">
      <h1 className="booking-header">ONE LEASING จองห้องประชุม / ห้องทำงาน</h1>
      <Row gutter={[24, 24]} justify="center">
        {rooms.map((room, index) => (
          <Col xs={24} sm={24} md={12} xl={8} key={index}>
            <Card
              title={room.title}
              variant={true}
              className="booking-card"
              actions={[
                <Text strong key="tel">
                  หรือโทร 0-4323-9888
                </Text>,
              ]}
              cover={
                <img
                  alt="cover"
                  src={room.cover}
                  className="card-cover-image"
                />
              }
            >
              <Space direction="vertical">
                <Text strong>รองรับ {room.capacity} ที่นั่ง</Text>
                <Text>{room.description}</Text>
              </Space>

              <p>
                <strong>THB{room.price} /ชั่วโมง</strong>
              </p>
              <Button type="primary" onClick={() => showModal(room)}>
                Book a room
              </Button>
            </Card>
          </Col>
        ))}
      </Row>

      <BookingRoomModal
        open={isModalOpen}
        onClose={setIsModalOpen}
        room={selectedRoom}
        onFinish={handleFinishBook}
      />

      {/* {bookingSuccess && (
        <Alert
          message={bookingSuccess}
          type="success"
          showIcon
          style={{ marginBottom: 16 }}
        />
      )} */}
    </div>
  );
}
